<?php
namespace App\Services\Sifi;
use App\Models\SifiMonitoringObject;

/** Reuses existing multi_source storage, comparison/save and session ownership gates. */
final class RealSearchWorkspace
{
 public const SCENARIOS=['api_fixture','api_no_result','api_quota','api_timeout','api_partial','api_web_2025'];
 public function liveCanonical(string $url):string{$p=parse_url($url);if(($p['scheme']??'')!=='https'||!in_array($p['host']??'',['id.wikipedia.org','doi.org'],true)||isset($p['port'])||isset($p['user'])||isset($p['pass'])||isset($p['query'])||isset($p['fragment'])||preg_match('/[\\x00-\\x20]/',$url))throw new \RuntimeException('RESULT_URL_POLICY');return $url;}
 public function execute(SifiMonitoringObject $o,array $plan,array $binding,string $scenario,array $providerIds=SearchProviderRegistry::IDS,string $mode='HTTP_FAKE',int $queryIndex=0,bool $recover=false,array $dateWindow=[]):array
 {
  if($mode==='HTTP_FAKE'){if(!in_array($scenario,self::SCENARIOS,true)||!app()->environment('testing')||config('sifi.real_search_fixture')!==true)throw new \RuntimeException('LIVE_SEARCH_LOCKED');}elseif($mode!=='LIVE'||$scenario!=='approved_live'||count($providerIds)!==1||array_diff($providerIds,[...SearchProviderRegistry::IDS,'TAVILY_KEYLESS','GDELT_DOC'])||config('sifi.real_search_live')!==true)throw new \RuntimeException('LIVE_SEARCH_LOCKED');
  if($scenario==='api_web_2025'){$providerIds=['TAVILY_KEYLESS','WIKIPEDIA_ID'];$dateWindow=['start'=>'2025-01-01','end'=>'2026-01-01'];}
  $binding['plan_sha256']=hash('sha256',json_encode($plan,JSON_THROW_ON_ERROR));
  // These values come from the authorized locked session, never request payload.
  if(($binding['owner_id']??null)!==$o->user_id||($binding['object_id']??null)!==$o->id||($binding['object_revision']??null)!==$o->revision||empty($binding['session_id']))throw new \RuntimeException('CONTEXT_MISMATCH');
  $entries=[];$calls=[];$raw=0;$bytes=0;$stop='COMPLETED';$seen=[];$start=hrtime(true);$limits=['query_limit'=>$mode==='LIVE'?1:min(2,(int)$plan['limits']['query_limit']),'provider_limit'=>count($providerIds),'simulated_call_limit'=>$mode==='LIVE'?1:4,'result_limit'=>min(10,(int)$plan['limits']['result_limit']),'metadata_byte_limit'=>65536,'time_limit_ms'=>15000,'network_request_limit'=>$mode==='LIVE'?1:0,'cost_limit'=>0];
  foreach(array_slice($plan['queries'],$mode==='LIVE'?$queryIndex:0,$limits['query_limit'],true) as $qi=>$query){foreach($providerIds as $id){
   if(count($calls)>=4){$stop='SIMULATED_CALL_LIMIT';break 2;}if((hrtime(true)-$start)/1e6>=$limits['time_limit_ms']){$stop='TIME_LIMIT';break 2;}
   $context=['mode'=>$mode,'query'=>$query['query'],'query_sha256'=>hash('sha256',$query['query']),'binding'=>$binding,'limit'=>5];
   if($dateWindow!==[]&&in_array($id,['TAVILY_KEYLESS','CROSSREF'],true))$context['date_window']=$dateWindow;$provider=$id==='TAVILY_KEYLESS'?new TavilySearchProvider():new CorpusSearchProvider($id);$packet=$recover?$provider->recover($context):$provider->search($context);
   if($packet['binding_sha256']!==hash('sha256',json_encode($binding,JSON_THROW_ON_ERROR))||$packet['query_sha256']!==$context['query_sha256'])throw new \RuntimeException('PROVENANCE_MISMATCH');
   $calls[]=['provider'=>$id,'query_index'=>$qi,'query'=>$query['query'],'query_sha256'=>$packet['query_sha256'],'binding_sha256'=>$packet['binding_sha256'],'response_sha256'=>$packet['response_sha256'],'state'=>$packet['state'],'response_bytes'=>$packet['response_bytes'],'retry_after_seconds'=>$packet['retry_after_seconds'],'retrieved_at'=>$packet['retrieved_at'],'fixture_loaded_at'=>$packet['fixture_loaded_at'],'simulated_call'=>$mode==='HTTP_FAKE','network_requests'=>$packet['network_requests']];
   if($bytes+$packet['response_bytes']>65536){$stop='METADATA_BYTE_LIMIT';break 2;}$bytes+=$packet['response_bytes'];
   foreach($packet['results'] as $item){
    $hay=$item['title'].' '.$item['snippet'];$excluded=false;foreach($plan['exclusions'] as $term)if(mb_stripos($hay,$term)!==false)$excluded=true;if($excluded)continue;
    $url=$mode==='HTTP_FAKE'?app(MultiSourceResearchWorkspace::class)->canonical($item['url']):(in_array($id,['TAVILY_KEYLESS','GDELT_DOC'],true)?TavilySearchProvider::safeMetadataUrl($item['url']):$this->liveCanonical($item['url']));$key=hash('sha256',$url);$raw++;$seen[$key]=true;
    $lineage=['provider'=>$id,'query_index'=>$qi,'query_sha256'=>$packet['query_sha256'],'binding_sha256'=>$packet['binding_sha256'],'result_key'=>$item['key'],'url'=>$url,'origin'=>$item['origin'],'snippet'=>$item['snippet'],'response_sha256'=>$packet['response_sha256'],'publication_precision'=>$item['publication_precision'],'attribution'=>$item['attribution']];
    if(isset($entries[$key])){$entries[$key]['lineage'][]=$lineage;continue;}if(count($entries)>=$limits['result_limit']){$stop='RESULT_LIMIT';continue;}
    $terms=MultiSourceFixtureSupport::words($hay);$hits=array_values(array_intersect($plan['question_terms'],$terms));$contextHits=array_values(array_intersect(MultiSourceFixtureSupport::words($o->name.' '.implode(' ',$o->aliases_json).' '.($o->geography??'')),$terms));$contextHits=array_values(array_diff($contextHits,['synthetic','fixture']));
    $entries[$key]=['id'=>$key,'title'=>$item['title'],'canonical_url'=>$url,'url'=>$url,'snippet'=>$item['snippet'],'snippet_kind'=>$item['snippet_kind'],'published_at'=>$item['published_at'],'publication_precision'=>$item['publication_precision'],'retrieved_at'=>$item['retrieved_at'],'fixture_loaded_at'=>$item['fixture_loaded_at'],'rights_state'=>$item['rights_state'],'attribution'=>$item['attribution'],'retrieval_allowed'=>false,'evidence_admission'=>'NONE','origins'=>[$item['origin']],'origin_state'=>'DECLARED_NOT_VERIFIED','lineage'=>[$lineage],'snippet_sha256'=>hash('sha256',$item['snippet']),'relevance'=>['score'=>count($hits)*3+count($contextHits),'question_hits'=>$hits,'context_hits'=>$contextHits],'relevance_group'=>$contextHits?'QUESTION_AND_OBJECT_MATCH':'QUESTION_MATCH']+($id==='GDELT_DOC'?['first_seen_at'=>$item['first_seen_at']??null]:[]);
   }
  }}
  $entries=array_values($entries);usort($entries,fn($a,$b)=>($b['relevance']['score']<=>$a['relevance']['score'])?:strcmp($a['id'],$b['id']));$pairs=[];
  foreach($entries as $i=>$a)foreach(array_slice($entries,$i+1) as $b){$withheld=($a['snippet_kind']??'')==='WITHHELD_PENDING_RIGHTS'||($b['snippet_kind']??'')==='WITHHELD_PENDING_RIGHTS';$left=$withheld?[]:MultiSourceFixtureSupport::words($a['snippet']);$right=$withheld?[]:MultiSourceFixtureSupport::words($b['snippet']);$sameOrigin=(bool)array_intersect($a['origins'],$b['origins']);$pairs[]=['left'=>$a['id'],'right'=>$b['id'],'shared_terms'=>array_slice(array_values(array_intersect($left,$right)),0,12),'left_only_terms'=>array_slice(array_values(array_diff($left,$right)),0,12),'right_only_terms'=>array_slice(array_values(array_diff($right,$left)),0,12),'shared_declared_origin'=>$sameOrigin,'possible_republication'=>!$withheld&&($sameOrigin||$a['snippet_sha256']===$b['snippet_sha256']),'independence'=>'NOT_VERIFIED','conclusion'=>$withheld?'Snippet tidak disimpan; kesamaan/perbedaan isi dan publikasi ulang belum dapat dinilai.':'Perbandingan metadata korpus berbeda; bukan verifikasi fakta atau corroboration independen.'];}
  if($stop==='COMPLETED'){$failed=(bool)array_filter($calls,fn($c)=>$c['state']!=='OK');$stop=$failed?($entries?'PARTIAL_COVERAGE':'NO_RESULTS_PROVIDER_ERRORS'):($entries?'COMPLETED':'NO_RESULTS');}
  return ['version'=>'sifi-corpus-search-1','mode'=>$mode==='LIVE'?'APPROVED_LIVE_CORPUS_METADATA':'SYNTHETIC_HTTP_FAKE_API_ADAPTER','entries'=>$entries,'comparisons'=>$pairs,'calls'=>$calls,'provider_ids'=>$providerIds,'plan_sha256'=>$binding['plan_sha256'],'binding_sha256'=>hash('sha256',json_encode($binding,JSON_THROW_ON_ERROR)),'budget'=>$limits,'usage'=>['simulated_calls'=>count($calls),'fixture_metadata_bytes'=>$bytes,'network_requests'=>array_sum(array_column($calls,'network_requests')),'documents_retrieved'=>0,'cost'=>0],'raw_result_count'=>$raw,'unique_result_count'=>count($entries),'collapsed_hits'=>max(0,$raw-count($seen)),'omitted_unique_count'=>count($seen)-count($entries),'stopping_reason'=>$stop,'coverage'=>$mode==='LIVE'?'Satu query pada provider yang disetujui; sampel terbatas, bukan penelusuran lengkap atau pengambilan dokumen.':'Adapter API Wikipedia Indonesia dan Crossref diuji dengan HTTP fake buatan sendiri. Bukan pencarian internet nyata.','independence'=>'NOT_VERIFIED','claim_verification'=>'NOT_PERFORMED_METADATA_ONLY','ai'=>'OFF','fixture_scenario'=>$scenario];
 }
}
